<script setup lang="ts">
import {computed,reactive,ref} from 'vue';
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';
import StudioAdminShell from '../../components/StudioAdminShell.vue';
import {useStudioNative} from '../../utils/studio-native';
import {adminCall,adminError,confirmAdmin,requestKey,today} from '../../utils/studio-admin';
import copy from '../../../../05_studio/src/content/business.json';
import {centsFromInput,money,type FinanceCategory,type FinanceDraft,type FinanceEntry,type FinancePage} from '../../../../05_studio/src/business-model';
const {language,keyboardOpen,shellStyle,say,changeLanguage}=useStudioNative();
const busy=ref(false),saving=ref(false),error=ref(''),amount=ref(''),entry=ref<FinanceEntry>(),categories=ref<FinanceCategory[]>([]),history=ref<any[]>([]),showHistory=ref(false),voiding=ref(false),reason=ref(''),initialized=ref(false);
let ident='',key=requestKey(),alive=true;
const draft=reactive<FinanceDraft>({kind:'expense',category:'experience',occurred_on:today(),customer_name:'',items:[''],amount_cents:null,payment_method:'',note:''});
const categoryNames=computed(()=>categories.value.map(c=>language.value==='zh'?c.zh:c.en));
async function load(force=false){if(busy.value||initialized.value&&!force)return;busy.value=true;error.value='';
 try{const [listing,detail]=await Promise.all([adminCall<FinancePage>('/manage/finance'),ident?adminCall<{entry:FinanceEntry;history:any[]}>('/manage/finance/'+ident):Promise.resolve(null)]);if(!alive)return;categories.value=listing.categories;
 if(detail){entry.value=detail.entry;history.value=detail.history;const e=detail.entry;Object.assign(draft,{kind:e.kind,category:e.category,occurred_on:e.occurred_on,customer_name:e.customer_name,items:[...e.items],amount_cents:e.amount_cents,payment_method:e.payment_method,note:e.note});amount.value=e.amount_cents===null?'':(e.amount_cents/100).toFixed(2);}initialized.value=true;}
 catch(e){error.value=adminError(e,say);}finally{busy.value=false;}}
async function save(){if(saving.value||!initialized.value)return;const value=centsFromInput(amount.value);error.value='';
 if(value===null&&!(entry.value?.source==='reservation'&&draft.kind==='income'&&!amount.value.trim())){error.value=say(copy.finance_amount_required);return;}
 const items=draft.items.map(s=>s.trim());if(items.some(s=>!s||s.length>200)){error.value=say(copy.invalid_items);return;}
 saving.value=true;try{const result=await adminCall<FinanceEntry>('/manage/finance'+(ident?'/'+ident:''),{...draft,items,amount_cents:value,...(entry.value?{version:entry.value.version}:{request_id:key})},ident?'PUT':'POST');ident=result.id;entry.value=result;await load(true);uni.showToast({title:say(copy.saved),icon:'none'});}catch(e){error.value=adminError(e,say);}finally{saving.value=false;}}
async function remove(){if(!entry.value||saving.value||!reason.value.trim())return;if(!await confirmAdmin(say(copy.void),say(copy.void_confirm),say(copy.void),say(copy.cancel)))return;
 saving.value=true;try{await adminCall('/manage/finance/'+entry.value.id,{version:entry.value.version,reason:reason.value},'DELETE');uni.navigateBack({fail:()=>uni.redirectTo({url:'/pages/studio/manage-finance'})});}catch(e){error.value=adminError(e,say);}finally{saving.value=false;}}
const paymentOptions=computed(()=>[copy.cash,copy.transfer,copy.card,copy.stored,copy.other_payment].map(say));
onLoad(q=>{ident=typeof q?.id==='string'?q.id:'';if(q?.kind==='income')draft.kind='income';});onShow(()=>void load());onUnload(()=>{alive=false;});
</script>
<template><StudioAdminShell :title="say(entry?copy.edit:draft.kind==='expense'?copy.add_expense:copy.add_income)" active="finance" back :language="language" :shell-style="shellStyle" :keyboard-open="keyboardOpen" :busy="busy" :error="error" @refresh="load(true)" @language="changeLanguage">
 <template v-if="initialized"><view v-if="entry?.source==='reservation'" class="admin-card admin-muted">{{say(copy.source_note)}}</view><view class="admin-card">
 <view class="admin-pair"><view class="admin-field"><text class="admin-label">{{say(copy.date)}}</text><picker mode="date" :value="draft.occurred_on" @change="draft.occurred_on=$event.detail.value"><view class="admin-input">{{draft.occurred_on}}</view></picker></view><view class="admin-field"><text class="admin-label">{{say(copy.amount)}}</text><input v-model="amount" type="digit" class="admin-input" :placeholder="entry?.needs_amount?say(copy.pending):'0.00'"/></view></view>
 <view class="admin-field"><text class="admin-label">{{say(copy.income)}} / {{say(copy.expense)}}</text><picker :range="[say(copy.income),say(copy.expense)]" :value="draft.kind==='income'?0:1" @change="draft.kind=Number($event.detail.value)===0?'income':'expense';draft.category='experience'"><view class="admin-input">{{say(draft.kind==='income'?copy.income:copy.expense)}}</view></picker></view>
 <template v-if="draft.kind==='income'"><view class="admin-field"><text class="admin-label">{{say(copy.category)}}</text><picker :range="categoryNames" :value="Math.max(0,categories.findIndex(c=>c.id===draft.category))" @change="draft.category=categories[Number($event.detail.value)].id"><view class="admin-input">{{categoryNames[categories.findIndex(c=>c.id===draft.category)]}}</view></picker></view><view class="admin-field"><text class="admin-label">{{say(copy.customer)}}</text><input v-model="draft.customer_name" class="admin-input" maxlength="120"/></view></template>
 <view class="admin-field"><text class="admin-label">{{say(draft.kind==='expense'?copy.shopping:draft.category==='experience'?copy.session:copy.purchased)}}</text><view v-for="(_,i) in draft.items" :key="i" class="admin-row"><input v-model="draft.items[i]" class="admin-input" maxlength="200"/><button class="admin-icon" :disabled="draft.items.length===1" :aria-label="say(copy.remove_item)" @tap="draft.items.splice(i,1)">−</button></view><button class="admin-secondary" :disabled="draft.items.length>=50" @tap="draft.items.push('')">+ {{say(copy.add_item)}}</button></view>
 <view v-if="draft.kind==='income'" class="admin-field"><text class="admin-label">{{say(copy.payment)}}</text><input v-model="draft.payment_method" class="admin-input" maxlength="80"/><view class="admin-filters"><button v-for="method in paymentOptions" :key="method" @tap="draft.payment_method=method">{{method}}</button></view></view><view class="admin-field"><text class="admin-label">{{say(copy.note)}}</text><textarea v-model="draft.note" class="admin-textarea" maxlength="1000" :adjust-position="false"/></view></view>
 <view v-if="history.length" class="admin-card admin-stack"><button class="admin-row" @tap="showHistory=!showHistory"><text>{{say(copy.history)}} · {{history.length}}</text><text>{{showHistory?'−':'+'}}</text></button><template v-if="showHistory"><view v-for="h in history" :key="h.id" class="admin-stack native-finance-history"><text class="admin-muted">{{h.snapshot.occurred_on}} · {{h.snapshot.customer_name}}</text><text>{{money(h.snapshot.amount_cents)}}</text></view></template></view>
 <button v-if="entry&&!voiding" class="admin-secondary" @tap="voiding=true">{{say(copy.void)}}</button><view v-if="voiding" class="admin-card admin-stack"><text class="admin-muted">{{say(copy.void_confirm)}}</text><input v-model="reason" class="admin-input" :placeholder="say(copy.void_reason)"/><button class="admin-secondary" :disabled="!reason.trim()||saving" @tap="remove">{{say(copy.void)}}</button></view></template>
 <template #actions><view class="admin-dock-row"><button class="admin-primary" :disabled="saving||busy||!initialized" hover-class="admin-pressed" @tap="save">{{say(saving?copy.saving:copy.save)}}</button></view></template>
 </StudioAdminShell></template>
<style scoped>.native-finance-history{border-top:1px solid #e2ebef;padding-top:10px}.admin-row>.admin-input{flex:1;min-width:0}</style>
